@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--ink:#f4f4ef;--muted:#9aa8b8;--cyan:#73f5e1;--amber:#ffb75e;--panel:rgba(7,15,27,.76)}*{box-sizing:border-box}html,body,#game{width:100%;height:100%;margin:0;overflow:hidden;background:#07101d}body{font-family:'Space Grotesk',sans-serif;color:var(--ink);touch-action:none;user-select:none;-webkit-user-select:none}#game{position:relative;isolation:isolate}#view{display:block;width:100%;height:100%;outline:0;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 42%,rgba(1,5,12,.24) 100%),linear-gradient(180deg,rgba(3,8,16,.22),transparent 22%,transparent 65%,rgba(3,8,16,.35)}
.topbar{position:absolute;z-index:2;left:0;right:0;top:0;padding:calc(20px + env(safe-area-inset-top)) 34px 16px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;background:linear-gradient(180deg,rgba(3,8,16,.7),transparent)}.brand{display:flex;align-items:center;gap:11px;letter-spacing:.11em}.brand-mark{color:var(--cyan);font-size:29px;line-height:1;text-shadow:0 0 16px #65ffe5}.brand strong,.brand small{display:block}.brand strong{font-size:12px;font-weight:700;letter-spacing:.16em}.brand small{font:9px 'DM Mono',monospace;color:#7f91a4;letter-spacing:.18em;margin-top:3px}.mission{font:10px 'DM Mono',monospace;letter-spacing:.16em;color:#d4dde5;display:flex;align-items:center;gap:9px}.status-dot{width:7px;height:7px;border-radius:50%;background:var(--amber);box-shadow:0 0 12px var(--amber);animation:pulse 1.8s infinite}.core-counter{justify-self:end;display:flex;align-items:baseline;gap:6px;padding:8px 12px;border:1px solid rgba(207,227,239,.15);background:rgba(7,15,27,.45);font-family:'DM Mono',monospace}.core-icon{color:var(--amber);font-size:14px}.core-counter #coreCount{font-size:19px;color:#fff}.core-counter small{font-size:10px;color:#8392a4}
.crosshair{position:absolute;left:50%;top:50%;width:26px;height:26px;transform:translate(-50%,-50%);pointer-events:none;opacity:.72}.crosshair i,.crosshair b{position:absolute;display:block;background:rgba(243,255,255,.82);box-shadow:0 0 6px rgba(106,255,226,.5)}.crosshair i{width:1px;height:8px;left:12px;top:0;box-shadow:0 18px 6px rgba(106,255,226,.5)}.crosshair b{width:8px;height:1px;left:0;top:12px;box-shadow:18px 0 6px rgba(106,255,226,.5)}.objective{position:absolute;left:34px;bottom:31px;display:flex;flex-direction:column;gap:5px;padding:13px 17px;border-left:2px solid var(--amber);background:linear-gradient(90deg,rgba(5,12,22,.75),transparent);text-shadow:0 1px 5px #06101a}.objective-kicker{font:9px 'DM Mono',monospace;letter-spacing:.2em;color:#9eb0c0}.objective strong{font-size:14px;font-weight:600;letter-spacing:.01em}.objective>span:last-child{font:10px 'DM Mono',monospace;color:#a6b3bf}.place-button{position:absolute;left:50%;bottom:30px;transform:translateX(-50%);display:flex;align-items:center;gap:11px;padding:14px 19px;border:1px solid rgba(255,183,94,.66);background:rgba(12,21,32,.82);color:#fff;font:600 11px 'DM Mono',monospace;letter-spacing:.12em;box-shadow:0 0 24px rgba(255,148,69,.13);cursor:pointer;transition:background .2s,border .2s,transform .2s}.place-button:hover{background:rgba(70,43,24,.92);border-color:#ffd49c;transform:translateX(-50%) translateY(-2px)}.button-glyph{font-size:18px;color:var(--amber);line-height:14px}.place-button kbd{font:10px 'DM Mono',monospace;border:1px solid #71808e;color:#a8b8c5;padding:3px 5px;margin-left:4px}.desktop-help{position:absolute;bottom:35px;right:34px;display:flex;gap:13px;font:10px 'DM Mono',monospace;color:#e3eaf0}.desktop-help span{display:flex;gap:6px;align-items:center}.desktop-help i{font-style:normal;color:#8291a2;font-size:8px;letter-spacing:.08em}.toast{position:absolute;top:96px;left:50%;transform:translate(-50%,-8px);padding:10px 15px;background:rgba(7,15,27,.86);border:1px solid rgba(255,183,94,.35);color:#f7d8ae;font:10px 'DM Mono',monospace;letter-spacing:.09em;opacity:0;transition:.24s;pointer-events:none;white-space:nowrap;z-index:4}.toast.show{opacity:1;transform:translate(-50%,0)}
.intro,.win-screen{position:absolute;inset:0;z-index:5;display:grid;place-items:center;background:rgba(4,9,17,.42);backdrop-filter:blur(3px);transition:opacity .55s,visibility .55s}.intro.hidden,.win-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-card,.win-card{width:min(450px,calc(100vw - 38px));padding:36px 40px 25px;background:linear-gradient(145deg,rgba(11,23,37,.96),rgba(7,13,24,.96));border:1px solid rgba(193,219,233,.18);box-shadow:0 24px 90px rgba(0,0,0,.42);position:relative}.intro-card:before,.win-card:before{content:'';position:absolute;inset:7px;border:1px solid rgba(193,219,233,.07);pointer-events:none}.intro-eyebrow{font:9px 'DM Mono',monospace;letter-spacing:.17em;color:#91a4b5;display:flex;align-items:center;gap:8px}.intro-eyebrow span{width:6px;height:6px;border-radius:50%;background:var(--cyan);box-shadow:0 0 10px var(--cyan)}h1{font-size:70px;line-height:.77;letter-spacing:-.08em;margin:28px 0 20px;font-weight:600}h1 em,.win-card h2 em{font-style:normal;color:var(--cyan)}.intro-lead{font-size:15px;color:#cad5dc;margin:0 0 23px}.intro-rule{height:1px;background:linear-gradient(90deg,rgba(115,245,225,.55),transparent);margin:0 0 20px}.intro-brief{display:flex;gap:13px;align-items:flex-start;color:#bdc9d2;font-size:12px;line-height:1.55}.intro-brief p{margin:0}.intro-brief b{color:#fff}.brief-icon{font-size:19px;color:var(--amber);padding-top:2px}.start-button{margin-top:24px;width:100%;border:0;background:var(--cyan);color:#07141d;padding:15px 16px;text-align:left;font:700 11px 'DM Mono',monospace;letter-spacing:.13em;cursor:pointer;transition:filter .2s,transform .2s;position:relative;z-index:1}.start-button:hover{filter:brightness(1.12);transform:translateY(-2px)}.start-button span{float:right;font-size:16px;margin-top:-3px}.intro-foot{display:flex;justify-content:space-between;margin-top:16px;color:#728393;font:8px 'DM Mono',monospace;letter-spacing:.12em}.win-screen{z-index:6}.win-card{text-align:center}.win-symbol{display:block;font-size:34px;color:var(--amber);margin:2px 0 14px;text-shadow:0 0 26px #ffb75e}.win-card h2{font-size:47px;line-height:.9;letter-spacing:-.07em;margin:18px 0}.win-card p{color:#b4c2cd;font-size:13px}.win-card .start-button{text-align:center}.loading{position:absolute;inset:0;z-index:10;display:grid;place-content:center;background:#07101d;color:#abc0d0;font:10px 'DM Mono',monospace;letter-spacing:.2em;transition:opacity .5s;pointer-events:none}.loading span{color:var(--cyan);text-align:center;letter-spacing:.4em;margin-top:14px}.loading.done{opacity:0}
.mobile-controls{display:none}.stick-zone{position:absolute;bottom:calc(26px + env(safe-area-inset-bottom));left:24px;width:130px;height:130px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:5px;color:#b8c9d4;font:8px 'DM Mono',monospace;letter-spacing:.16em}.stick-ring{width:82px;height:82px;border:1px solid rgba(197,225,237,.33);border-radius:50%;background:rgba(7,16,29,.28);display:grid;place-items:center;box-shadow:inset 0 0 24px rgba(116,242,225,.08)}.stick-knob{width:37px;height:37px;border:1px solid rgba(115,245,225,.65);border-radius:50%;background:rgba(115,245,225,.23);box-shadow:0 0 16px rgba(115,245,225,.22);transform:translate(0,0)}.look-label{position:absolute;right:23px;bottom:calc(42px + env(safe-area-inset-bottom));font:8px 'DM Mono',monospace;letter-spacing:.15em;color:rgba(219,232,239,.65)}
@keyframes pulse{50%{opacity:.42;box-shadow:0 0 4px var(--amber)}}@media(max-width:700px){.topbar{padding:calc(15px + env(safe-area-inset-top)) 16px 12px;grid-template-columns:1fr auto;}.mission{position:absolute;left:50%;top:calc(66px + env(safe-area-inset-top));transform:translateX(-50%);white-space:nowrap;font-size:8px}.brand{gap:7px}.brand-mark{font-size:25px}.brand strong{font-size:10px}.brand small{font-size:8px}.core-counter{padding:6px 9px}.core-counter #coreCount{font-size:16px}.objective{left:15px;bottom:calc(166px + env(safe-area-inset-bottom));padding:9px 12px}.objective strong{font-size:12px}.objective>span:last-child{font-size:8px}.objective-kicker{font-size:8px}.place-button{bottom:calc(23px + env(safe-area-inset-bottom));left:auto;right:17px;transform:none;padding:12px 12px;gap:8px;font-size:9px}.place-button:hover{transform:translateY(-2px)}.place-button kbd{display:none}.desktop-help{display:none}.mobile-controls{display:block}.stick-zone{left:11px;bottom:calc(19px + env(safe-area-inset-bottom))}.look-label{bottom:calc(38px + env(safe-area-inset-bottom));right:16px}.toast{top:105px;font-size:9px}.intro-card{padding:29px 25px 20px}.intro-foot{font-size:7px}h1{font-size:63px}.crosshair{width:22px;height:22px}.crosshair i{left:10px}.crosshair b{top:10px}}@media(max-height:520px) and (orientation:landscape){.intro-card{padding:18px 28px;width:min(560px,calc(100vw - 32px))}h1{font-size:48px;margin:17px 0 12px}.intro-lead{margin-bottom:13px}.intro-rule{margin-bottom:12px}.intro-brief{font-size:11px}.start-button{margin-top:15px;padding:12px}.intro-foot{margin-top:9px}.objective{bottom:100px}.stick-zone{transform:scale(.8);transform-origin:bottom left}.place-button{bottom:26px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#view');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true;
renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace;
renderer.toneMapping=THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure=1.16;
const scene=new THREE.Scene();
scene.background=new THREE.Color('#081222');
scene.fog=new THREE.FogExp2('#081222',.018);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.08,90);
const clock=new THREE.Clock();
const raycaster=new THREE.Raycaster();
const center=new THREE.Vector2(0,0);
const player={x:0,z:7.1,yaw:0,pitch:-.025,speed:5.2,started:false,cores:0,placed:false,won:false,cooldown:0};
const keys=new Set();
const mat=(color,roughness=.7,metalness=.1,extra={})=>new THREE.MeshStandardMaterial({color,roughness,metalness,...extra});
const mats={floor:mat('#172536',.82,.35),wall:mat('#1b2b3d',.72,.35),wallDark:mat('#101d2d',.75,.28),trim:mat('#506477',.43,.68),gold:mat('#d9904e',.4,.65),goldGlow:new THREE.MeshBasicMaterial({color:'#ffad5c'}),cyan:new THREE.MeshBasicMaterial({color:'#64ffe4'}),cyanGlass:new THREE.MeshBasicMaterial({color:'#56f7e3',transparent:true,opacity:.11,side:THREE.DoubleSide,depthWrite:false}),orange:new THREE.MeshBasicMaterial({color:'#ff9d59'}),orangeGlass:new THREE.MeshBasicMaterial({color:'#ff9b53',transparent:true,opacity:.14,side:THREE.DoubleSide,depthWrite:false}),black:mat('#08111c',.48,.25),white:mat('#dce5eb',.3,.25),crystal:mat('#ffc86a',.23,.25,{emissive:'#ff851d',emissiveIntensity:1.2}),
};
const boxGeo=new THREE.BoxGeometry(1,1,1);
function box(parent,name,pos,size,material,cast=true,receive=true){const o=new THREE.Mesh(boxGeo,material);o.name=name;o.position.set(...pos);o.scale.set(...size);o.castShadow=cast;o.receiveShadow=receive;parent.add(o);return o;}
function addLight(color,intensity,pos,distance=0){const l=new THREE.PointLight(color,intensity,distance,2);l.position.set(...pos);scene.add(l);return l;}
const world=new THREE.Group();scene.add(world);
scene.add(new THREE.HemisphereLight('#a5d6e8','#151927',1.45));
const keyLight=new THREE.DirectionalLight('#e3f2ff',2.2);keyLight.position.set(-5,12,8);keyLight.castShadow=true;keyLight.shadow.mapSize.set(1024,1024);keyLight.shadow.camera.left=-16;keyLight.shadow.camera.right=16;keyLight.shadow.camera.top=18;keyLight.shadow.camera.bottom=-18;scene.add(keyLight);

// Modular chamber architecture
const floor=box(world,'deck',[0,-.22,0],[24,.44,25],mats.floor,false,true);
const grid=new THREE.GridHelper(24,24,'#325063','#24394b');grid.position.y=.008;world.add(grid);
// Recessed floor seams and perimeter rails
for(let x=-10;x<=10;x+=2)box(world,'floor seam',[x,-.008,0],[.025,.012,24,mats.trim],false,false);
for(let z=-10;z<=10;z+=2)box(world,'floor seam',[0,-.008,z],[24,.012,.025],mats.trim,false,false);
// Room shell with the south fixed gate and north access gate openings
box(world,'west wall',[-12,2.4,0],[.6,4.8,24],mats.wall);
box(world,'east wall',[12,2.4,0],[.6,4.8,24],mats.wall);
box(world,'north wall',[0,2.4,-12],[24,.6,.6],mats.wall);
// South wall is split around the fixed portal
box(world,'south wall left',[-6.3,2.4,12],[11.4,4.8,.6],mats.wall);
box(world,'south wall right',[6.3,2.4,12],[11.4,4.8,.6],mats.wall);
box(world,'south lintel',[0,4.45,12],[1.2,.7,.6],mats.wall);
// Portal partition dividing the test chamber from the memory field
box(world,'partition left',[-6,2.35,0],[12,4.7,.65],mats.wallDark);
box(world,'partition right',[6,2.35,0],[12,4.7,.65],mats.wallDark);
box(world,'partition crown',[0,4.55,0],[.65,.5,.65],mats.wallDark);
// Gold receiver plate on the south face of the partition
box(world,'receiver plate backing',[0,2.05,.39],[3.55,3.8,.14],mats.black);
box(world,'receiver plate',[0,2.05,.29],[3.27,3.52,.08],mats.gold);
box(world,'plate inset',[0,2.05,.235],[2.98,3.23,.04],mats.wallDark);
for(const x of [-1.52,1.52])for(const y of [.48,3.62]){const bolt=new THREE.Mesh(new THREE.CylinderGeometry(.055,.055,.05,12),mats.trim);bolt.rotation.x=Math.PI/2;bolt.position.set(x,y,.19);world.add(bolt);}
// Wall panels, ribs, and cyan guide strips
for(let z=-10;z<=10;z+=2){box(world,'wall rib',[-11.66,2.35,z],[.12,4.45,.12],mats.trim);box(world,'wall rib',[11.66,2.35,z],[.12,4.45,.12],mats.trim);}
for(let x=-10;x<=10;x+=2){box(world,'ceiling rib',[x,4.65,-11.65],[.12,.12,.12],mats.trim);}
for(const side of [-1,1]){
  const strip=box(world,'guide light',[side*11.54,.56,0],[.035,.035,22],mats.cyan,false,false);strip.material=mats.cyan;
  for(const z of [-8,-4,4,8])box(world,'wall light',[side*11.55,2.35,z],[.035,.45,.16],mats.cyan,false,false);
}
// Ceiling lamps cast soft pools of light
for(const z of [-8,-4,4,8]){box(world,'lamp housing',[0,4.58,z],[2.5,.15,.65],mats.black);const lamp=new THREE.Mesh(new THREE.BoxGeometry(2.15,.04,.32),new THREE.MeshBasicMaterial({color:'#b8fff3'}));lamp.position.set(0,4.48,z);world.add(lamp);addLight('#7fffea',2.0,[0,3.9,z],9);}
addLight('#ffad5c',2.2,[0,2.2,.1],7);

function portalFrame({name,pos,rotationY,color,glass,active=false}){
 const g=new THREE.Group();g.name=name;g.position.set(...pos);g.rotation.y=rotationY;world.add(g);
 const halo=new THREE.Mesh(new THREE.TorusGeometry(.79,.115,12,64),new THREE.MeshBasicMaterial({color,transparent:true,opacity:active?.95:.82}));halo.scale.y=1.48;g.add(halo);
 const inner=new THREE.Mesh(new THREE.CircleGeometry(.72,48),glass);inner.scale.y=1.42;inner.position.z=-.035;g.add(inner);
 const outer=new THREE.Mesh(new THREE.TorusGeometry(.92,.035,8,64),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.45}));outer.scale.y=1.48;outer.position.z=.025;g.add(outer);
 const cap=new THREE.Mesh(new THREE.BoxGeometry(2.4,.1,.13),mats.black);cap.position.y=1.47;g.add(cap);
 const light=new THREE.PointLight(color,active?2.8:1.8,5);light.position.set(0,0,.4);g.add(light);
 return {group:g,halo,inner,light};
}
// Target slot (the player's one movable gate) and fixed cyan gate at the south wall
const targetPortal=portalFrame({name:'one movable portal',pos:[0,1.93,.12],rotationY:0,color:'#ff9d59',glass:mats.orangeGlass,active:true});
const fixedPortal=portalFrame({name:'fixed cyan portal',pos:[0,1.93,11.67],rotationY:Math.PI,color:'#64ffe4',glass:mats.cyanGlass});
const targetHalo=targetPortal.halo;
const receiverPad=world.getObjectByName('plate inset');
receiverPad.material=mat('#26394a',.4,.5,{emissive:'#b16c35',emissiveIntensity:.3});

// Entrance and extraction marking on the south-side floor
function floorRing(x,z,color,r=.95){const ring=new THREE.Mesh(new THREE.RingGeometry(r-.09,r,48),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(x,.018,z);world.add(ring);return ring;}
const extractRing=floorRing(0,7.05,'#64ffe4',1.05);
const extractCore=new THREE.Mesh(new THREE.CylinderGeometry(.34,.48,.12,6),mats.black);extractCore.position.set(0,.08,7.05);world.add(extractCore);
for(let i=0;i<4;i++){const rune=new THREE.Mesh(new THREE.BoxGeometry(.035,.025,.28),new THREE.MeshBasicMaterial({color:'#73f5e1'}));rune.position.set(Math.sin(i*Math.PI/2)*.79,.035,7.05+Math.cos(i*Math.PI/2)*.79);rune.rotation.y=i*Math.PI/2;world.add(rune);}
addLight('#59ffe0',1.4,[0,.4,7.05],4);
// Cores in the isolated memory field
const cores=[];
for(const [i,x] of [-7,0,7].entries()){
 const g=new THREE.Group();g.position.set(x,.85,-6.3+(i===1?-1:0));g.userData.collected=false;
 const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.42,0),mats.crystal);crystal.scale.set(.78,1.32,.78);crystal.rotation.z=.2;crystal.castShadow=true;g.add(crystal);
 const orbit=new THREE.Mesh(new THREE.TorusGeometry(.65,.025,6,40),new THREE.MeshBasicMaterial({color:'#ffbf68',transparent:true,opacity:.75}));orbit.rotation.x=Math.PI/2;g.add(orbit);
 const glow=new THREE.PointLight('#ff9c49',1.3,3);glow.position.y=.1;g.add(glow);
 const pedestal=new THREE.Mesh(new THREE.CylinderGeometry(.52,.63,.24,8),mats.black);pedestal.position.y=-.72;g.add(pedestal);
 const baseRing=new THREE.Mesh(new THREE.TorusGeometry(.54,.035,8,32),mats.goldGlow);baseRing.rotation.x=Math.PI/2;baseRing.position.y=-.57;g.add(baseRing);
 world.add(g);cores.push(g);
}
// Distant machinery and amber hazard chevrons add depth beyond the partition
for(const x of [-9,-6,-3,3,6,9]){
 box(world,'north field console',[x,.62,-9.6],[1.05,1.25,.42],mats.wallDark);
 box(world,'console display',[x,.82,-9.37],[.72,.38,.04],x%2?mats.cyan:mats.goldGlow,false,false);
}
for(const x of [-10,-8,-6,-4,-2,2,4,6,8,10]){
 const stripe=box(world,'partition warning stripe',[x,.1,.335],[.52,.12,.018],mats.goldGlow,false,false);stripe.rotation.y=.35;
}

